  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In rhesus monkeys, m-AMSA achieved CSF concentrations only 1-3% of systemic concentrations after IV dosing, directly demonstrating poor BBB permeability in a high-transfer analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Imatinib brain uptake is restricted by P-gp and Bcrp1 efflux at the BBB in situ; the query's multiple basic centers and high molecular weight make efflux-mediated restriction highly plausible.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Imatinib CSF levels were less than 1% of plasma levels in pharmacokinetic analysis, providing direct evidence of poor CNS penetration in a structurally related anilino-heteroaryl system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "L-365,260 showed very low total brain uptake (<0.8% dose/g) in mice, indicating very low BBB permeability despite substantial lipophilic/aromatic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A close analogue with an anilino-heteroaryl core and polar amide substituent had a brain unbound/plasma unbound ratio of 0.08, classified as poor brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "GSK2982772 exhibits limited brain concentration due to P-gp efflux, supporting the expectation that large, polar, basic molecules in this chemical space are efflux-limited at the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted fail: multiple high-transfer experimental analogues show very low CSF/brain penetration, efflux-limited BBB transport, and poor unbound brain partitioning. The query's high molecular weight, high TPSA, multiple basic centers, and low neutral fraction align with these liabilities, and no transferable evidence supports meaningful CNS access.",
